/** The collections of the database, as Mongoose models. They reflect it: Mongoose never creates collections or indexes with them. */
import { Schema, type Connection, type Model } from 'mongoose'

/** A document as the driver gives it, by the stored names of its fields */
export type Stored = Record<string, unknown>

/** The model of every collection */
export interface Models {
  products: Model<Stored>
  auditLog: Model<Stored>
}

/** Defines the model of every collection on `connection`. */
export function defineModels(connection: Connection): Models {
  /** The 'products' collection. */
  const products = new Schema(
    {
      sku: String,
      price: Schema.Types.Decimal128,
      stock: Schema.Types.Double,
      weight: Schema.Types.Double,
      big: Schema.Types.BigInt,
      created: Date,
      reference: Schema.Types.UUID,
      picture: Buffer,
      key: Schema.Types.UUID,
      pattern: Schema.Types.Mixed,
      patterns: { type: [Schema.Types.Mixed], default: undefined },
      text: String,
      parts: { type: [new Schema({ name: String, inner: new Schema({ deep: Schema.Types.Mixed }, { _id: false, strict: false, minimize: false }) }, { _id: false, strict: false, minimize: false })], default: undefined },
      low: Schema.Types.BigInt,
    },
    { collection: 'products', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )

  /** The 'audit-log' collection. */
  const auditLog = new Schema(
    {
