/** Operations on audit-log: what each one checks before it writes. */
import type { AuditLogCreate, AuditLogRead, AuditLogUpdate } from '../dtos/audit-log.js'
import { AuditLog } from '../entities/audit-log.js'
import { NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['id', 'at', 'by'])

/** Operations on audit-log. Repositories commit every write. */
export class AuditLogService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "audit-log" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: AuditLog | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of AuditLog' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.id
      if (value == null) {
        if (creating || 'id' in values) errors.push({ field: '_id', message: 'is required' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('AuditLog', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: AuditLog | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The AuditLog with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<AuditLog> {
    const entity = await uow.auditLog.findById(id)
    if (entity === null) throw new NotFoundError('AuditLog', id)
    return entity
  }

  /** The AuditLog as services return it. */
  private static read(entity: AuditLog): AuditLogRead {
    return { id: entity.id, at: entity.at, by: entity.by }
  }

  /** Stores a new AuditLog after checking it. */
  async createAuditLog(data: AuditLogCreate): Promise<AuditLogRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.auditLog.insert(Object.assign(new AuditLog(), values))
      return AuditLogService.read(created)
    })
  }

  /** The AuditLog with this key; NotFoundError when there is none. */
  async getAuditLog(id: string): Promise<AuditLogRead> {
    return AuditLogService.read(await this.find(this.uow, id))
  }

  /** A page of audit-log, by primary key. */
  async listAuditLogs(offset = 0, limit = 50): Promise<Page<AuditLogRead>> {
    const page = await this.uow.auditLog.list(offset, limit)
    return { ...page, items: page.items.map((entity) => AuditLogService.read(entity)) }
  }

  /** Changes the given values of a AuditLog. */
  async updateAuditLog(id: string, data: AuditLogUpdate): Promise<AuditLogRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.auditLog.update(current)
      return AuditLogService.read(updated)
    })
  }

  /** Deletes a AuditLog. */
  async deleteAuditLog(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.auditLog.delete(current)
    })
  }
}

