  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "products" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Product' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.parts
      if (value != null) {
        errors.push(...problems(value, DOCUMENTS.parts, 'parts'))
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Product', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Product with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Product> {
    const entity = await uow.products.findById(id)
    if (entity === null) throw new NotFoundError('Product', id)
    return entity
  }

  /** The Product as services return it. */
  private static read(entity: Product): ProductRead {
    return { id: entity.id, sku: entity.sku, price: entity.price, stock: entity.stock, weight: entity.weight, big: entity.big, created: entity.created, reference: entity.reference, picture: entity.picture, key: entity.key, pattern: entity.pattern, patterns: entity.patterns, text: entity.text, parts: entity.parts, low: entity.low }
  }

  /** Stores a new Product after checking it. */
  async createProduct(data: ProductCreate): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.products.insert(Object.assign(new Product(), values))
      return ProductService.read(created)
    })
  }

  /** The Product with this key; NotFoundError when there is none. */
  async getProduct(id: string): Promise<ProductRead> {
    return ProductService.read(await this.find(this.uow, id))
  }

  /** A page of products, by primary key. */
  async listProducts(offset = 0, limit = 50): Promise<Page<ProductRead>> {
    const page = await this.uow.products.list(offset, limit)
    return { ...page, items: page.items.map((entity) => ProductService.read(entity)) }
  }

  /** Changes the given values of a Product. */
  async updateProduct(id: string, data: ProductUpdate): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.products.update(current)
      return ProductService.read(updated)
    })
  }

  /** Deletes a Product. */
  async deleteProduct(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.products.delete(current)
    })
  }

  /** Adds an item to patterns. */
  async addPattern(id: string, pattern: unknown): Promise<ProductRead> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.products.addPattern(id, pattern)
      if (updated === null) throw new NotFoundError('Product', id)
      return ProductService.read(updated)
    })
  }

  /** Removes an item from patterns, by its position. */
  async removePattern(id: string, position: number): Promise<ProductRead> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(position in (current.patterns ?? []))) throw new NotFoundError('Pattern', position)
      const updated = await uow.products.removePattern(id, position, (current.patterns ?? []).length)
      if (updated === null) throw new ConflictError('Product', 'was changed by someone else since it was read', ['patterns'])
      return ProductService.read(updated)
    })
  }

  /** Adds an item to parts. */
  async addPart(id: string, part: { name?: string | null; inner?: { deep?: unknown | null } | null }): Promise<ProductRead> {
    const errors = problems([part], DOCUMENTS.parts, 'parts')
    if (errors.length > 0) throw new ValidationFailedError('Product', errors)
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.products.addPart(id, part)
      if (updated === null) throw new NotFoundError('Product', id)
      return ProductService.read(updated)
    })
  }

  /** Removes an item from parts, by its position. */
  async removePart(id: string, position: number): Promise<ProductRead> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(position in (current.parts ?? []))) throw new NotFoundError('Part', position)
      const updated = await uow.products.removePart(id, position, (current.parts ?? []).length)
      if (updated === null) throw new ConflictError('Product', 'was changed by someone else since it was read', ['parts'])
      return ProductService.read(updated)
    })
  }
}

