    const found = await service.getAuditLog(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new AuditLogService(uow)
    const n = 100
    const error: unknown = await service.createAuditLog({ ...pick<AuditLogCreate>(newAuditLog(1), CREATE_FIELDS), id: null } as unknown as AuditLogCreate).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['_id'])
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new AuditLogService(uow)
    await expect(service.getAuditLog('missing')).rejects.toBeInstanceOf(NotFoundError)
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new AuditLogService(uow)
    const n = 100
    const created = await service.createAuditLog(pick<AuditLogCreate>(newAuditLog(1), CREATE_FIELDS))
    await service.deleteAuditLog(created.id)
    await expect(service.getAuditLog(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

/** Fields of the create DTO */
const CREATE_FIELDS = ['id', 'at', 'by']

/** The values a DTO takes, from a row the factories made. */
function pick<T>(row: object, fields: readonly string[]): T {
  return Object.fromEntries(Object.entries(row).filter(([name]) => fields.includes(name))) as T
}

