/** Rows for the tests: valid values for every column, and the rows they point to. */
import { AuditLog } from '../src/entities/audit-log.js'
import { Product } from '../src/entities/product.js'
import type { UnitOfWork } from '../src/unit-of-work.js'

/** A valid Product that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newProduct(n = 1, values: Partial<Product> = {}): Product {
  return Object.assign(new Product(), { sku: `sku-${n}`, price: `${n % 10000}.50`, stock: n + 0.5, weight: n + 0.5, big: n, created: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)), reference: `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, picture: Buffer.from([n % 256]), key: `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, pattern: { n }, patterns: [], text: `text-${n}`, parts: [{ name: `name-${n}`, inner: { deep: { n } } }], low: n }, values)
}

/** A stored Product. */
export async function addProduct(uow: UnitOfWork, n = 1): Promise<Product> {
  return uow.products.insert(newProduct(n))
}

/** A valid AuditLog that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newAuditLog(n = 1, values: Partial<AuditLog> = {}): AuditLog {
  return Object.assign(new AuditLog(), { id: `id-${n}`, at: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)), by: { n } }, values)
}

/** A stored AuditLog. */
export async function addAuditLog(uow: UnitOfWork, n = 1): Promise<AuditLog> {
  return uow.auditLog.insert(newAuditLog(n))
}

