/** Tests of the "products" table. */
import { describe, expect, it } from 'vitest'
import type { ProductCreate } from '../src/dtos/product.js'
import { NotFoundError } from '../src/errors.js'
import { ProductService } from '../src/services/product.js'
import { MemoryUnitOfWork } from '../src/unit-of-work.js'
import { useTestDatabase } from './database.js'
import { addProduct, newProduct } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const mongoUow = useTestDatabase()

describe('products repository', () => {
  it('is stored and read back', async () => {
    const uow = mongoUow()
    const stored = await addProduct(uow, 1)
    const found = await uow.products.findById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
  })

  it('lists rows by key', async () => {
    const uow = mongoUow()
    await addProduct(uow, 1)
    await addProduct(uow, 2)
    const page = await uow.products.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = mongoUow()
    const stored = await addProduct(uow, 1)
    stored.sku = 'changed'
    await uow.products.update(stored)
    const found = await uow.products.findById(stored.id)
    expect(found?.sku).toBe('changed')
  })

  it('adds and removes one item of patterns', async () => {
    const uow = mongoUow()
    const stored = await addProduct(uow, 1)
    const before = stored.patterns?.length ?? 0
    const item = ((n: number) => ({ n }))(7)
    const added = await uow.products.addPattern(stored.id, item)
    expect(added?.patterns).toHaveLength(before + 1)
    expect(added?.patterns?.at(-1)).toMatchObject(item)
    const removed = await uow.products.removePattern(stored.id, added!.patterns!.length - 1, added!.patterns!.length)
    expect(removed?.patterns).toHaveLength(before)
    expect(await uow.products.removePattern(stored.id, 0, before + 5)).toBeNull()
  })

  it('adds and removes one item of parts', async () => {
    const uow = mongoUow()
    const stored = await addProduct(uow, 1)
    const before = stored.parts?.length ?? 0
    const item = ((n: number) => ({ name: `name-${n}`, inner: { deep: { n } } }))(7)
    const added = await uow.products.addPart(stored.id, item)
    expect(added?.parts).toHaveLength(before + 1)
    expect(added?.parts?.at(-1)).toMatchObject(item)
    const removed = await uow.products.removePart(stored.id, added!.parts!.length - 1, added!.parts!.length)
    expect(removed?.parts).toHaveLength(before)
    expect(await uow.products.removePart(stored.id, 0, before + 5)).toBeNull()
  })

  it('is deleted', async () => {
    const uow = mongoUow()
    const stored = await addProduct(uow, 1)
    await uow.products.delete(stored)
    expect(await uow.products.findById(stored.id)).toBeNull()
  })
})

describe('ProductService', () => {
  it('creates a valid row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ProductService(uow)
    const n = 100
    const created = await service.createProduct(pick<ProductCreate>(newProduct(1), CREATE_FIELDS))
    const found = await service.getProduct(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ProductService(uow)
    await expect(service.getProduct('ffffffffffffffffffffffff')).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ProductService(uow)
    const n = 100
    const created = await service.createProduct(pick<ProductCreate>(newProduct(1), CREATE_FIELDS))
    const updated = await service.updateProduct(created.id, { sku: 'changed' })
    expect(updated.sku).toBe('changed')
  })

  it('adds and removes one item of patterns', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ProductService(uow)
    const n = 100
    const created = await service.createProduct(pick<ProductCreate>(newProduct(1), CREATE_FIELDS))
    const before = created.patterns?.length ?? 0
    const item = ((n: number) => ({ n }))(7)
    const added = await service.addPattern(created.id, item)
    expect(added.patterns).toHaveLength(before + 1)
    const removed = await service.removePattern(created.id, added.patterns!.length - 1)
    expect(removed.patterns).toHaveLength(before)
    await expect(service.removePattern(created.id, 99)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('adds and removes one item of parts', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ProductService(uow)
    const n = 100
    const created = await service.createProduct(pick<ProductCreate>(newProduct(1), CREATE_FIELDS))
    const before = created.parts?.length ?? 0
    const item = ((n: number) => ({ name: `name-${n}`, inner: { deep: { n } } }))(7)
    const added = await service.addPart(created.id, item)
    expect(added.parts).toHaveLength(before + 1)
    const removed = await service.removePart(created.id, added.parts!.length - 1)
    expect(removed.parts).toHaveLength(before)
    await expect(service.removePart(created.id, 99)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ProductService(uow)
    const n = 100
    const created = await service.createProduct(pick<ProductCreate>(newProduct(1), CREATE_FIELDS))
    await service.deleteProduct(created.id)
    await expect(service.getProduct(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

/** Fields of the create DTO */
const CREATE_FIELDS = ['sku', 'price', 'stock', 'weight', 'big', 'created', 'reference', 'picture', 'key', 'pattern', 'patterns', 'text', 'parts', 'low']

/** The values a DTO takes, from a row the factories made. */
function pick<T>(row: object, fields: readonly string[]): T {
  return Object.fromEntries(Object.entries(row).filter(([name]) => fields.includes(name))) as T
}

